-- PostgreSQL-only authoritative facts. Native compatibility names are views.
CREATE SCHEMA chain;
REVOKE ALL ON SCHEMA chain FROM PUBLIC;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
CREATE DOMAIN public.hash28type AS bytea CHECK(octet_length(VALUE)=28);
CREATE DOMAIN public.hash32type AS bytea CHECK(octet_length(VALUE)=32);
CREATE DOMAIN public.word31type AS integer CHECK(VALUE>=0);
CREATE DOMAIN public.word63type AS bigint CHECK(VALUE>=0);
CREATE DOMAIN public.uinteger AS integer CHECK(VALUE>=0);
CREATE DOMAIN public.txindex AS smallint CHECK(VALUE>=0);
CREATE DOMAIN public.word64type AS numeric CHECK(VALUE=trunc(VALUE) AND VALUE>=0 AND VALUE<=18446744073709551615);
CREATE DOMAIN public.lovelace AS numeric CHECK(VALUE=trunc(VALUE) AND VALUE>=0 AND VALUE<=18446744073709551615);
CREATE DOMAIN public.asset32type AS bytea CHECK(octet_length(VALUE)<=32);
CREATE TABLE chain.metadata(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE chain.generations(id bigint PRIMARY KEY CHECK(id>=0),parent bigint REFERENCES chain.generations(id),status text NOT NULL CHECK(status IN ('pending','ready','source_conflict')),source text NOT NULL,start_height public.word31type NOT NULL,start_index public.word31type NOT NULL,target_height public.word31type NOT NULL,witness_height public.word31type NOT NULL,manifest jsonb NOT NULL,CHECK(parent IS NULL OR parent<id));
CREATE UNIQUE INDEX one_pending_generation ON chain.generations((status)) WHERE status='pending';
CREATE TABLE chain.service_state(id integer PRIMARY KEY CHECK(id=1),owner text NOT NULL,schema_version integer NOT NULL,canonical_ready bigint REFERENCES chain.generations(id),revoked boolean NOT NULL DEFAULT false,publication_serial bigint NOT NULL DEFAULT 0,migration_state text NOT NULL CHECK(migration_state IN ('importing','restoring','ready')));
CREATE TABLE chain.checkpoints(generation bigint REFERENCES chain.generations(id),phase text,unit text,receipt jsonb NOT NULL,PRIMARY KEY(generation,phase,unit));
CREATE TABLE chain.provenance(generation bigint REFERENCES chain.generations(id),kind text,key text,source_id text,PRIMARY KEY(generation,kind,key));
CREATE TABLE chain.sync_jobs(id text PRIMARY KEY,body jsonb NOT NULL CHECK(octet_length(body::text)<=65536));
CREATE TABLE chain.blocks(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),hash public.hash32type PRIMARY KEY,height public.word31type NOT NULL,parent_hash public.hash32type,epoch public.word31type,slot public.word63type,time timestamp NOT NULL,tx_count public.word63type NOT NULL,first_generation bigint NOT NULL REFERENCES chain.generations(id));
CREATE TABLE chain.generation_blocks(generation bigint REFERENCES chain.generations(id),height public.word31type,hash public.hash32type NOT NULL REFERENCES chain.blocks(hash),PRIMARY KEY(generation,height));
CREATE INDEX generation_blocks_hash ON chain.generation_blocks(hash);
CREATE TABLE chain.transactions(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),hash public.hash32type PRIMARY KEY,block_hash public.hash32type NOT NULL REFERENCES chain.blocks(hash),tx_index public.word31type NOT NULL,valid integer NOT NULL CHECK(valid=1),first_generation bigint NOT NULL REFERENCES chain.generations(id),UNIQUE(block_hash,tx_index));
CREATE TABLE chain.datums(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),hash public.hash32type PRIMARY KEY,value jsonb NOT NULL,first_generation bigint NOT NULL REFERENCES chain.generations(id));
CREATE TABLE chain.outputs(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),tx_hash public.hash32type REFERENCES chain.transactions(hash),output_index public.txindex,address text NOT NULL,value public.lovelace NOT NULL,datum_hash public.hash32type REFERENCES chain.datums(hash),first_generation bigint NOT NULL REFERENCES chain.generations(id),PRIMARY KEY(tx_hash,output_index));
-- `ordinal`: position among ALL ordinary inputs of the spending transaction in ledger order (origin
-- hash, index), as the source reports it; outside the fact contract, it places the input's served ID.
CREATE TABLE chain.inputs(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),tx_hash public.hash32type REFERENCES chain.transactions(hash),origin_hash public.hash32type,origin_index public.txindex,first_generation bigint NOT NULL REFERENCES chain.generations(id),ordinal smallint NOT NULL CONSTRAINT inputs_ordinal_range CHECK(ordinal BETWEEN 0 AND 4095),PRIMARY KEY(tx_hash,origin_hash,origin_index),FOREIGN KEY(origin_hash,origin_index) REFERENCES chain.outputs(tx_hash,output_index),UNIQUE(origin_hash,origin_index),CONSTRAINT inputs_transaction_ordinal UNIQUE(tx_hash,ordinal));
CREATE TABLE chain.assets(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),policy public.hash28type,name public.asset32type,first_generation bigint NOT NULL REFERENCES chain.generations(id),PRIMARY KEY(policy,name));
-- `ordinal`: position among ALL assets of the output in ledger order (policy, name bytewise).
CREATE TABLE chain.output_assets(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),tx_hash public.hash32type,output_index public.txindex,policy public.hash28type,name public.asset32type,quantity public.word64type NOT NULL,first_generation bigint NOT NULL REFERENCES chain.generations(id),ordinal smallint NOT NULL CONSTRAINT output_assets_ordinal_range CHECK(ordinal BETWEEN 0 AND 4095),PRIMARY KEY(tx_hash,output_index,policy,name),FOREIGN KEY(tx_hash,output_index) REFERENCES chain.outputs(tx_hash,output_index),FOREIGN KEY(policy,name) REFERENCES chain.assets(policy,name),CONSTRAINT output_assets_output_ordinal UNIQUE(tx_hash,output_index,ordinal));
CREATE TABLE chain.mints(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),tx_hash public.hash32type REFERENCES chain.transactions(hash),policy public.hash28type,name public.asset32type,quantity numeric NOT NULL CHECK(quantity=trunc(quantity) AND quantity BETWEEN -99999999999999999999 AND 99999999999999999999),first_generation bigint NOT NULL REFERENCES chain.generations(id),PRIMARY KEY(tx_hash,policy,name),FOREIGN KEY(policy,name) REFERENCES chain.assets(policy,name));
CREATE TABLE chain.epoch_nonces(epoch public.word31type PRIMARY KEY,nonce public.hash32type NOT NULL,max_tx_size public.word31type NOT NULL,first_generation bigint NOT NULL REFERENCES chain.generations(id));
CREATE TABLE chain.pools(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),pool_hash public.hash28type PRIMARY KEY);
CREATE TABLE chain.epoch_stakes(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE CHECK(id>0),epoch public.word31type,pool_hash public.hash28type REFERENCES chain.pools(pool_hash),amount public.lovelace NOT NULL,first_generation bigint NOT NULL REFERENCES chain.generations(id),PRIMARY KEY(epoch,pool_hash));
CREATE INDEX idx_block_block_no ON chain.blocks(height);
CREATE INDEX idx_block_slot_no ON chain.blocks(slot);
CREATE INDEX idx_tx_block_id ON chain.transactions(block_hash);
CREATE INDEX idx_tx_out_tx_id ON chain.outputs(tx_hash);
CREATE INDEX idx_tx_out_data_hash ON chain.outputs(datum_hash);
CREATE INDEX idx_tx_out_address ON chain.outputs(address);
CREATE INDEX idx_tx_in_tx_in_id ON chain.inputs(tx_hash);
CREATE INDEX idx_tx_in_tx_out_id_tx_out_index ON chain.inputs(origin_hash,origin_index);
CREATE INDEX idx_multi_asset_policy_name ON chain.assets(policy,name);
CREATE INDEX idx_multi_asset_policy_name_hex ON chain.assets(encode(policy,'hex'),encode(name,'hex'));
CREATE INDEX idx_ma_tx_out_ident ON chain.output_assets(policy,name);
CREATE INDEX idx_ma_tx_out_id_ident ON chain.output_assets(tx_hash,output_index,policy,name);
CREATE VIEW chain.ready_generation AS SELECT g.* FROM chain.service_state s JOIN chain.generations g ON g.id=s.canonical_ready WHERE s.id=1 AND s.owner='db-sync-alt' AND s.schema_version=1 AND NOT s.revoked AND s.migration_state='ready' AND g.status='ready';
CREATE FUNCTION chain.membership(generation_id bigint) RETURNS TABLE(height integer,hash bytea) LANGUAGE sql STABLE AS $$
 WITH RECURSIVE lineage(id,ceiling) AS (
 SELECT id,witness_height FROM chain.generations WHERE id=generation_id
 UNION ALL SELECT p.id,p.target_height FROM lineage l JOIN chain.generations c ON c.id=l.id JOIN chain.generations p ON p.id=c.parent
 ) SELECT gb.height::integer,gb.hash::bytea FROM lineage l JOIN chain.generation_blocks gb ON gb.generation=l.id AND gb.height<=l.ceiling
$$;
CREATE VIEW chain.ready_lineage AS WITH RECURSIVE lineage(id,ceiling) AS (
 SELECT id,witness_height FROM chain.ready_generation UNION ALL
 SELECT p.id,p.target_height FROM lineage l JOIN chain.generations c ON c.id=l.id JOIN chain.generations p ON p.id=c.parent
) SELECT * FROM lineage;
CREATE VIEW public.block AS SELECT b.id,b.hash,b.epoch AS epoch_no,b.slot AS slot_no,b.height AS block_no,b.time,b.tx_count FROM chain.ready_lineage l JOIN chain.generation_blocks m ON m.generation=l.id AND m.height<=l.ceiling JOIN chain.blocks b ON b.hash=m.hash;
CREATE VIEW public.block_parent AS SELECT b.hash,b.parent_hash FROM chain.blocks b JOIN public.block p USING(hash);
CREATE VIEW public.tx AS SELECT t.id,t.hash,b.id AS block_id,t.tx_index AS block_index,(t.valid=1) AS valid_contract FROM chain.transactions t JOIN chain.blocks b ON b.hash=t.block_hash CROSS JOIN chain.ready_generation g WHERE t.first_generation<=g.id AND b.first_generation<=g.id;
CREATE VIEW public.tx_out AS SELECT o.id,t.id AS tx_id,o.output_index AS index,o.address,o.value,o.datum_hash AS data_hash,NULL::bigint AS consumed_by_tx_id FROM chain.outputs o JOIN chain.transactions t ON t.hash=o.tx_hash CROSS JOIN chain.ready_generation g WHERE o.first_generation<=g.id AND t.first_generation<=g.id;
CREATE VIEW public.tx_in AS SELECT i.id,t.id AS tx_in_id,origin.id AS tx_out_id,i.origin_index AS tx_out_index FROM chain.inputs i JOIN chain.transactions t ON t.hash=i.tx_hash JOIN chain.transactions origin ON origin.hash=i.origin_hash CROSS JOIN chain.ready_generation g WHERE i.first_generation<=g.id AND t.first_generation<=g.id AND origin.first_generation<=g.id;
CREATE VIEW public.datum AS SELECT id,hash,value FROM chain.datums WHERE first_generation<=(SELECT id FROM chain.ready_generation);
CREATE VIEW public.multi_asset AS SELECT id,policy,name FROM chain.assets WHERE first_generation<=(SELECT id FROM chain.ready_generation);
CREATE VIEW public.ma_tx_out AS SELECT a.id,a.quantity,o.id AS tx_out_id,m.id AS ident FROM chain.output_assets a JOIN chain.outputs o ON o.tx_hash=a.tx_hash AND o.output_index=a.output_index JOIN chain.assets m ON m.policy=a.policy AND m.name=a.name WHERE a.first_generation<=(SELECT id FROM chain.ready_generation) AND o.first_generation<=(SELECT id FROM chain.ready_generation) AND m.first_generation<=(SELECT id FROM chain.ready_generation);
CREATE VIEW public.ma_tx_mint AS SELECT a.id,a.quantity,t.id AS tx_id,m.id AS ident FROM chain.mints a JOIN chain.transactions t ON t.hash=a.tx_hash JOIN chain.assets m ON m.policy=a.policy AND m.name=a.name CROSS JOIN chain.ready_generation g WHERE a.first_generation<=g.id AND t.first_generation<=g.id AND m.first_generation<=g.id;
CREATE VIEW public.epoch_param AS SELECT epoch AS epoch_no,nonce,max_tx_size FROM chain.epoch_nonces WHERE first_generation<=(SELECT id FROM chain.ready_generation);
CREATE VIEW public.pool_hash AS SELECT p.id,p.pool_hash AS hash_raw FROM chain.pools p WHERE EXISTS(SELECT 1 FROM chain.epoch_stakes s WHERE s.pool_hash=p.pool_hash AND s.first_generation<=(SELECT id FROM chain.ready_generation));
CREATE VIEW public.epoch_stake AS SELECT s.id,p.id AS pool_id,s.amount,s.epoch AS epoch_no FROM chain.epoch_stakes s JOIN chain.pools p USING(pool_hash) WHERE s.first_generation<=(SELECT id FROM chain.ready_generation);
CREATE VIEW public.tx_metadata AS SELECT NULL::bigint AS id,NULL::public.word64type AS key,NULL::bigint AS tx_id,NULL::jsonb AS json WHERE false;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA chain FROM PUBLIC;
